export const getListRemoteFilesUrl = (id: string,
    params?: ListRemoteFilesParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/remote-connections/${id}/files?${stringifiedParams}` : `/api/remote-connections/${id}/files`
}

export const listRemoteFiles = async (id: string,
    params?: ListRemoteFilesParams, options?: Parameters<typeof apiFetch>[1]): Promise<ListRemoteFiles200> => {

  return apiFetch<ListRemoteFiles200>(getListRemoteFilesUrl(id,params),
  {
    ...options,
    method: 'GET'


  }
);}





