export const getSummariseRemoteFilesUrl = (id: string,) => {




  return `/api/remote-connections/${id}/files/summary`
}

export const summariseRemoteFiles = async (id: string,
    summariseRemoteFilesBody: SummariseRemoteFilesBody, options?: Parameters<typeof apiFetch>[1]): Promise<SummariseRemoteFiles200> => {

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(h as Iterable<Iterable<string>>, (entry) => Array.from(entry) as [string, string]),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
return apiFetch<SummariseRemoteFiles200>(getSummariseRemoteFilesUrl(id),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(summariseRemoteFilesBody)
  }
);}





export const getSummariseRemoteFilesQueryKey = (id: string,
    summariseRemoteFilesBody?: BodyType<SummariseRemoteFilesBody>,) => {
    return [
    'POST', `/api/remote-connections/${id}/files/summary`, summariseRemoteFilesBody
    ] as const;
    }


